func findByKey[T interface{ GetKey() string }](key string, ts ...T) (t T, _ bool) {
	return find(func(t T) bool { return t.GetKey() == key }, ts...)
}

func find[T any](match func(T) bool, ts ...T) (t T, _ bool) {
	for _, t := range ts {
		if match(t) {
			return t, true
		}
	}

	return t, false
}

func paginate[T any](params storage.QueryParams, less func(i, j int) bool, items ...T) (storage.ResultSet[T], error) {
	if len(items) == 0 {
		return storage.ResultSet[T]{}, nil
	}

	set := storage.ResultSet[T]{
		Results: items,
	}

	// sort by created_at and specified order
	sort.Slice(set.Results, func(i, j int) bool {
		if params.Order != storage.OrderAsc {
			i, j = j, i
		}

		return less(i, j)
	})

	// parse page token as an offset integer
	var offset int
	v, err := strconv.ParseInt(params.PageToken, 10, 64)
	if params.PageToken != "" && err != nil {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("pageToken is not valid: %q", params.PageToken)
	}

	offset = int(v)

	if offset >= len(set.Results) {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("invalid offset: %d", offset)
	}

	// 0 means no limit on page size (all items from offset)
	if params.Limit == 0 {
		set.Results = set.Results[offset:]
		return set, nil
	}

	// ensure end of page does not exceed entire set
	end := offset + int(params.Limit)
	if end > len(set.Results) {
		end = len(set.Results)
	} else if end < len(set.Results) {
		// set next page token given there are more entries
		set.NextPageToken = fmt.Sprintf("%d", end)
	}

	// reduce results set to requested page
	set.Results = set.Results[offset:end]

	return set, nil
}

func (ss *StoreSnapshot) getNamespace(key string) (namespace, error) {
	ns, ok := ss.ns[key]
	if !ok {
		return namespace{}, errs.ErrNotFoundf("namespace %q", key)
	}

	return *ns, nil
}

package s3

import (
	"context"
	"fmt"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/s3"

	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/s3fs"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

// Source represents an implementation of an fs.SnapshotSource
// This implementation is backed by an S3 bucket
type Source struct {
	logger *zap.Logger
	s3     *s3.Client

	endpoint string
	region   string
	bucket   string
	prefix   string
	interval time.Duration
}

// NewSource constructs a Source.
func NewSource(logger *zap.Logger, bucket string, opts ...containers.Option[Source]) (*Source, error) {
	s := &Source{
		logger:   logger,
		bucket:   bucket,
		interval: 60 * time.Second,
	}

	containers.ApplyAll(s, opts...)

	s3opts := make([](func(*config.LoadOptions) error), 0)
	if s.region != "" {
		s3opts = append(s3opts, config.WithRegion(s.region))
	}
	if s.endpoint != "" {
		customResolver := aws.EndpointResolverWithOptionsFunc(func(service, region string, options ...interface{}) (aws.Endpoint, error) {
			if service == s3.ServiceID {
				return aws.Endpoint{
					PartitionID:       "aws",
					URL:               s.endpoint,
					HostnameImmutable: true,
					SigningRegion:     s.region,
				}, nil
			}
			return aws.Endpoint{}, fmt.Errorf("unknown endpoint requested")
		})
		s3opts = append(s3opts, config.WithEndpointResolverWithOptions(customResolver))
	}
	cfg, err := config.LoadDefaultConfig(context.Background(),
		s3opts...)
	if err != nil {
		return nil, err
	}
	s.s3 = s3.NewFromConfig(cfg)

	return s, nil
}

// WithPrefix configures the prefix for s3
func WithPrefix(prefix string) containers.Option[Source] {
	return func(s *Source) {
		s.prefix = prefix
	}
}

// WithRegion configures the region for s3
func WithRegion(region string) containers.Option[Source] {
	return func(s *Source) {
		s.region = region
	}
}

// WithEndpoint configures the region for s3
func WithEndpoint(endpoint string) containers.Option[Source] {
	return func(s *Source) {
		s.endpoint = endpoint
	}
}

// WithPollInterval configures the interval in which we will restore
// the s3 fs.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
	return func(s *Source) {
		s.interval = tick
	}
}

// Get returns a *sourcefs.StoreSnapshot for the local filesystem.
func (s *Source) Get() (*storagefs.StoreSnapshot, error) {
	fs, err := s3fs.New(s.logger, s.s3, s.bucket, s.prefix)
	if err != nil {
		return nil, err
	}

	return storagefs.SnapshotFromFS(s.logger, fs)
}

// Subscribe feeds S3 populated *StoreSnapshot instances onto the provided channel.
// It blocks until the provided context is cancelled.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
	defer close(ch)

	ticker := time.NewTicker(s.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			snap, err := s.Get()
			if err != nil {
				s.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			s.logger.Debug("updating local store snapshot")

			ch <- snap
		}
	}
}

// String returns an identifier string for the store type.
func (s *Source) String() string {
	return "s3"
}

package git

import (
	"context"
	"errors"
	"fmt"
	"io/fs"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/config"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/transport"
	"github.com/go-git/go-git/v5/storage/memory"
	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/gitfs"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

// Source is an implementation of storage/fs.FSSource
// This implementation is backed by a Git repository and it tracks an upstream reference.
// When subscribing to this source, the upstream reference is tracked
// by polling the upstream on a configurable interval.
type Source struct {
	logger *zap.Logger
	repo   *git.Repository

	url      string
	ref      string
	hash     plumbing.Hash
	interval time.Duration
	auth     transport.AuthMethod
}

// WithRef configures the target reference to be used when fetching
// and building fs.FS implementations.
// If it is a valid hash, then the fixed SHA value is used.
// Otherwise, it is treated as a reference in the origin upstream.
func WithRef(ref string) containers.Option[Source] {
	return func(s *Source) {
		if plumbing.IsHash(ref) {
			s.hash = plumbing.NewHash(ref)
			return
		}

		s.ref = ref
	}
}

// WithPollInterval configures the interval in which origin is polled to
// discover any updates to the target reference.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
	return func(s *Source) {
		s.interval = tick
	}
}

// WithAuth returns an option which configures the auth method used
// by the provided source.
func WithAuth(auth transport.AuthMethod) containers.Option[Source] {
	return func(s *Source) {
		s.auth = auth
	}
}

// NewSource constructs and configures a Source.
// The source uses the connection and credential details provided to build
// fs.FS implementations around a target git repository.
func NewSource(logger *zap.Logger, url string, opts ...containers.Option[Source]) (_ *Source, err error) {
	source := &Source{
		logger:   logger.With(zap.String("repository", url)),
		url:      url,
		ref:      "main",
		interval: 30 * time.Second,
	}
	containers.ApplyAll(source, opts...)

	field := zap.Stringer("ref", plumbing.NewBranchReferenceName(source.ref))
	if source.hash != plumbing.ZeroHash {
		field = zap.Stringer("SHA", source.hash)
	}
	source.logger = source.logger.With(field)

	source.repo, err = git.Clone(memory.NewStorage(), nil, &git.CloneOptions{
		Auth: source.auth,
		URL:  source.url,
	})
	if err != nil {
		return nil, err
	}

	return source, nil
}

// Get builds a new store snapshot based on the configure Git remote and reference.
func (s *Source) Get() (_ *storagefs.StoreSnapshot, err error) {
	var fs fs.FS
	if s.hash != plumbing.ZeroHash {
		fs, err = gitfs.NewFromRepoHash(s.logger, s.repo, s.hash)
	} else {
		fs, err = gitfs.NewFromRepo(s.logger, s.repo, gitfs.WithReference(plumbing.NewRemoteReferenceName("origin", s.ref)))
	}
	if err != nil {
		return nil, err
	}

	return storagefs.SnapshotFromFS(s.logger, fs)
}

// Subscribe feeds gitfs implementations of fs.FS onto the provided channel.
// It blocks until the provided context is cancelled (it will be called in a goroutine).
// It closes the provided channel before it returns.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
	defer close(ch)

	// NOTE: theres is no point subscribing to updates for a git Hash
	// as it is atomic and will never change.
	if s.hash != plumbing.ZeroHash {
		s.logger.Info("skipping subscribe as static SHA has been configured")
		return
	}

	ticker := time.NewTicker(s.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			s.logger.Debug("fetching from remote")
			if err := s.repo.Fetch(&git.FetchOptions{
				Auth: s.auth,
				RefSpecs: []config.RefSpec{
					config.RefSpec(fmt.Sprintf(
						"+%s:%s",
						plumbing.NewBranchReferenceName(s.ref),
						plumbing.NewRemoteReferenceName("origin", s.ref),
					)),
				},
			}); err != nil {
				if errors.Is(err, git.NoErrAlreadyUpToDate) {
					s.logger.Debug("store already up to date")
					continue
				}

				s.logger.Error("failed fetching remote", zap.Error(err))
				continue
			}

			snap, err := s.Get()
			if err != nil {
				s.logger.Error("failed creating snapshot from fs", zap.Error(err))
				continue
			}

			ch <- snap

			s.logger.Debug("finished fetching from remote")
		}
	}
}

// String returns an identifier string for the store type.
func (*Source) String() string {
	return "git"
}

package oci

import "errors"

const (
	// MediaTypeFliptFeatures is the OCI media type for a flipt features artifact
	MediaTypeFliptFeatures = "application/vnd.io.flipt.features.v1"
	// MediaTypeFliptNamespace is the OCI media type for a flipt features namespace artifact
	MediaTypeFliptNamespace = "application/vnd.io.flipt.features.namespace.v1"

	// AnnotationFliptNamespace is an OCI annotation key which identifies the namespace key
	// of the annotated flipt namespace artifact
	AnnotationFliptNamespace = "io.flipt.features.namespace"
)

var (
	// ErrMissingMediaType is returned when a descriptor is presented
	// without a media type
	ErrMissingMediaType = errors.New("missing media type")
	// ErrUnexpectedMediaType is returned when an unexpected media type
	// is found on a target manifest or descriptor
	ErrUnexpectedMediaType = errors.New("unexpected media type")
)

package oci

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"path"
	"strings"
	"time"

	"github.com/opencontainers/go-digest"
	v1 "github.com/opencontainers/image-spec/specs-go/v1"
	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/containers"
	"oras.land/oras-go/v2"
	"oras.land/oras-go/v2/content"
	"oras.land/oras-go/v2/content/memory"
	"oras.land/oras-go/v2/content/oci"
	"oras.land/oras-go/v2/registry"
	"oras.land/oras-go/v2/registry/remote"
)

// Store is a type which can retrieve Flipt feature files from a target repository and reference
// Repositories can be local (OCI layout directories on the filesystem) or a remote registry
type Store struct {
	reference registry.Reference
	store     oras.ReadOnlyTarget
	local     oras.Target
}

// NewStore constructs and configures an instance of *Store for the provided config
func NewStore(conf *config.OCI) (*Store, error) {
	scheme, repository, match := strings.Cut(conf.Repository, "://")

	// support empty scheme as remote and https
	if !match {
		repository = scheme
		scheme = "https"
	}

	ref, err := registry.ParseReference(repository)
	if err != nil {
		return nil, err
	}

	store := &Store{
		reference: ref,
		local:     memory.New(),
	}
	switch scheme {
	case "http", "https":
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = scheme == "http"

		store.store = remote
	case "flipt":
		if ref.Registry != "local" {
			return nil, fmt.Errorf("unexpected local reference: %q", conf.Repository)
		}

		store.store, err = oci.New(path.Join(conf.BundleDirectory, ref.Repository))
		if err != nil {
			return nil, err
		}
	default:
		return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

	return store, nil
}

// FetchOptions configures a call to Fetch
type FetchOptions struct {
	IfNoMatch digest.Digest
}

// FetchResponse contains any fetched files for the given tracked reference
// If Matched == true, then the supplied IfNoMatch digest matched and Files should be nil
type FetchResponse struct {
	Digest  digest.Digest
	Files   []fs.File
	Matched bool
}

// IfNoMatch configures the call to Fetch to return early if the supplied
// digest matches the target manifest pointed at by the underlying reference
// This is a cache optimization to skip re-fetching resources if the contents
// has already been seen by the caller
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
	return func(fo *FetchOptions) {
		fo.IfNoMatch = digest
	}
}

// Fetch retrieves the associated files for the tracked repository and reference
// It can optionally be configured to skip fetching given the caller has a digest
// that matches the current reference target
func (s *Store) Fetch(ctx context.Context, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
	var options FetchOptions
	containers.ApplyAll(&options, opts...)

	desc, err := oras.Copy(ctx,
		s.store,
		s.reference.Reference,
		s.local,
		s.reference.Reference,
		oras.DefaultCopyOptions)
	if err != nil {
		return nil, err
	}

	bytes, err := content.FetchAll(ctx, s.local, desc)
	if err != nil {
		return nil, err
	}

	var manifest v1.Manifest
	if err = json.Unmarshal(bytes, &manifest); err != nil {
		return nil, err
	}

	var d digest.Digest
	{
		// shadow manifest so that we can safely
		// strip annotations before calculating
		// the digest
		manifest := manifest
		manifest.Annotations = map[string]string{}
		bytes, err := json.Marshal(&manifest)
		if err != nil {
			return nil, err
		}

		d = digest.FromBytes(bytes)
		if d == options.IfNoMatch {
			return &FetchResponse{Matched: true, Digest: d}, nil
		}
	}

	files, err := s.fetchFiles(ctx, manifest)
	if err != nil {
		return nil, err
	}

	return &FetchResponse{Files: files, Digest: d}, nil
}

// fetchFiles retrieves the associated flipt feature content files from the content fetcher.
// It traverses the provided manifests and returns a slice of file instances with appropriate
// content type extensions.
func (s *Store) fetchFiles(ctx context.Context, manifest v1.Manifest) ([]fs.File, error) {
	var files []fs.File

	created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
	if err != nil {
		return nil, err
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
		}

		switch encoding {
		case "", "json", "yaml", "yml":
		default:
			return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
		}

		rc, err := s.store.Fetch(ctx, layer)
		if err != nil {
			return nil, err
		}

		files = append(files, &File{
			ReadCloser: rc,
			info: FileInfo{
				desc:     layer,
				encoding: encoding,
				mod:      created,
			},
		})
	}

	return files, nil
}

func getMediaTypeAndEncoding(layer v1.Descriptor) (mediaType, encoding string, _ error) {
	var ok bool
	if mediaType = layer.MediaType; mediaType == "" {
		return "", "", ErrMissingMediaType
	}

	if mediaType, encoding, ok = strings.Cut(mediaType, "+"); !ok {
		encoding = "json"
	}

	return
}

// File is a wrapper around a flipt feature state files contents.
type File struct {
	io.ReadCloser
	info FileInfo
}

// Seek attempts to seek the embedded read-closer.
// If the embedded read closer implements seek, then it delegates
// to that instances implementation. Alternatively, it returns
// an error signifying that the File cannot be seeked.
func (f *File) Seek(offset int64, whence int) (int64, error) {
	if seek, ok := f.ReadCloser.(io.Seeker); ok {
		return seek.Seek(offset, whence)
	}

	return 0, errors.New("seeker cannot seek")
}

func (f *File) Stat() (fs.FileInfo, error) {
	return &f.info, nil
}

// FileInfo describes a flipt features state file instance.
type FileInfo struct {
	desc     v1.Descriptor
	encoding string
	mod      time.Time
}

func (f FileInfo) Name() string {
	return f.desc.Digest.Hex() + "." + f.encoding
}

func (f FileInfo) Size() int64 {
	return f.desc.Size
}

func (f FileInfo) Mode() fs.FileMode {
	return fs.ModePerm
}

func (f FileInfo) ModTime() time.Time {
	return f.mod
}

func (f FileInfo) IsDir() bool {
	return false
}

func (f FileInfo) Sys() any {
	return nil
}

